mapper.select:
SELECT
    ,
    u.nickname AS author_name,
    u.username AS author_username,
    c.name     AS category_name
FROM `article` a
LEFT JOIN `user` u     ON u.id = a.author_id
LEFT JOIN `category` c ON c.id = a.category_id


        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
             OR a.summary LIKE CONCAT('%', #{keyword}, '%'))

    AND a.category_id = #{categoryId}
    AND a.author_id = #{authorId}
    AND a.status = #{status}

        AND EXISTS (
            SELECT 1 FROM `article_tag` at
            WHERE at.article_id = a.id AND at.tag_id = #{tagId}
        )


ORDER BY a.is_top DESC, a.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM `article` a


        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
             OR a.summary LIKE CONCAT('%', #{keyword}, '%'))

    AND a.category_id = #{categoryId}
    AND a.author_id = #{authorId}
    AND a.status = #{status}

        AND EXISTS (
            SELECT 1 FROM `article_tag` at
            WHERE at.article_id = a.id AND at.tag_id = #{tagId}
        )

mapper.update:
UPDATE `article`
title = #{title}, summary = #{summary}, content = #{content}, cover_image = #{coverImage}, category_id = #{categoryId}, status = #{status}, is_top = #{isTop}, is_original = #{isOriginal}, source_url = #{sourceUrl}, publish_time = #{publishTime},
WHERE id = #{id}

UPDATE `article`
SET like_count = GREATEST(0, like_count + #{delta})
WHERE id = #{id}
